{"explanation":"The law of cosines says c² = a² + b² − 2ab·cos γ, where γ is the angle between sides a and b. You can read it as the Pythagorean theorem plus a correction term. When γ = 90°, cos γ = 0, so the correction disappears and you get a² + b² = c². When γ is smaller than 90°, the side opposite it is shorter than Pythagoras would predict, so the term subtracts. When γ is larger than 90°, cos γ is negative, so the term adds and c² comes out bigger. In the picture, b·cos γ is the signed length of b's shadow on side a (the red segment). The correction is just −2 × a × that shadow. Drag the yellow point A, or the point B, to watch the correction change sign.","manimCode":"const C = [-5, -2, 0];
const baseY = -2;

const title = new MathTex({ latex: 'c^2 = \\underbrace{a^2 + b^2}_{\\text{Pythagoras}} \\; \\underbrace{-\\,2ab\\cos\\gamma}_{\\text{correction}}' });
await title.waitForRender();
title.scale(0.8);
title.moveTo([0, 3.1, 0]);
scene.add(title);

const dotA = new Dot({ point: [-3.8, 1.0, 0], color: YELLOW });
const dotB = new Dot({ point: [-1.5, baseY, 0], color: WHITE });
const dotC = new Dot({ point: C, color: WHITE });

function seg(color, w) {
  const p = new Polygon({ vertices: [[0,0,0],[1,0,0]], color: color });
  p.setStrokeWidth(w).setFillOpacity(0);
  return p;
}

const fillTri = new Polygon({ vertices: [C, [-1.5, baseY, 0], [-3.8, 1, 0]], color: WHITE });
fillTri.setStrokeWidth(0);
fillTri.setFill(BLUE_E, 0.25);

const sideA = seg(BLUE, 5);
const sideB = seg(GREEN, 5);
const sideC = seg(YELLOW, 5);
const dropLine = seg(GRAY, 2);
const shadow = seg(RED, 7);
const baseExt = seg(GRAY_D, 1);

const sector = new Polygon({ vertices: [C, [C[0]+0.5, C[1], 0], [C[0], C[1]+0.5, 0]], color: ORANGE });
sector.setStrokeWidth(1);
sector.setFill(ORANGE, 0.35);

scene.add(fillTri, baseExt, sector, dropLine, shadow, sideA, sideB, sideC, dotC, dotB, dotA);

let labels = [];
let readouts = [];

function mkText(str, color, size, pos) {
  const t = new Text({ text: str, color: color, fontSize: size });
  t.moveTo(pos);
  scene.add(t);
  return t;
}

function update() {
  const A = dotA.getCenter();
  const B = dotB.getCenter();
  const a = Math.hypot(B[0]-C[0], B[1]-C[1]);
  const b = Math.hypot(A[0]-C[0], A[1]-C[1]);
  const c = Math.hypot(A[0]-B[0], A[1]-B[1]);
  const gamma = Math.atan2(A[1]-C[1], A[0]-C[0]);
  const cosG = Math.cos(gamma);
  const H = [C[0] + b*cosG, baseY, 0];

  fillTri.setVertices([C, B, A]);
  sideA.setVertices([C, B]);
  sideB.setVertices([C, A]);
  sideC.setVertices([B, A]);
  dropLine.setVertices([A, H]);
  shadow.setVertices([[C[0], baseY - 0.18, 0], [H[0], baseY - 0.18, 0]]);
  baseExt.setVertices([[Math.min(H[0], C[0]) - 0.3, baseY, 0], [Math.max(B[0], H[0]) + 0.3, baseY, 0]]);

  const pts = [C];
  const r = 0.55;
  for (let i = 0; i <= 20; i++) {
    const th = gamma * i / 20;
    pts.push([C[0] + r*Math.cos(th), C[1] + r*Math.sin(th), 0]);
  }
  sector.setVertices(pts);

  labels.forEach(l => scene.remove(l));
  readouts.forEach(l => scene.remove(l));
  labels = [];
  readouts = [];

  labels.push(mkText('a', BLUE, 28, [(C[0]+B[0])/2, baseY - 0.5, 0]));
  labels.push(mkText('b', GREEN, 28, [(C[0]+A[0])/2 - 0.3*Math.sin(gamma), (C[1]+A[1])/2 + 0.3*Math.cos(gamma), 0]));
  labels.push(mkText('c', YELLOW, 28, [(A[0]+B[0])/2 + 0.3, (A[1]+B[1])/2 + 0.2, 0]));
  labels.push(mkText('γ', ORANGE, 26, [C[0] + 0.85*Math.cos(gamma/2), C[1] + 0.85*Math.sin(gamma/2), 0]));
  labels.push(mkText('A', YELLOW, 24, [A[0], A[1] + 0.35, 0]));

  const deg = gamma * 180 / Math.PI;
  const pyth = a*a + b*b;
  const corr = -2*a*b*cosG;
  const x0 = 3.6;
  readouts.push(mkText('a = ' + a.toFixed(2) + '   b = ' + b.toFixed(2), WHITE, 24, [x0, 1.6, 0]));
  readouts.push(mkText('γ = ' + deg.toFixed(1) + '°   cos γ = ' + cosG.toFixed(3), ORANGE, 24, [x0, 1.0, 0]));
  readouts.push(mkText('a² + b² = ' + pyth.toFixed(2), WHITE, 26, [x0, 0.2, 0]));
  readouts.push(mkText('−2ab cos γ = ' + (corr >= 0 ? '+' : '') + corr.toFixed(2), RED, 26, [x0, -0.4, 0]));
  readouts.push(mkText('c² = ' + (pyth + corr).toFixed(2) + '   (measured: ' + (c*c).toFixed(2) + ')', YELLOW, 24, [x0, -1.0, 0]));
  let msg, col;
  if (Math.abs(deg - 90) < 1.5) { msg = 'γ = 90°: correction vanishes → Pythagoras!'; col = GREEN; }
  else if (deg < 90) { msg = 'γ < 90°: c is shorter, subtract'; col = TEAL; }
  else { msg = 'γ > 90°: c is longer, add'; col = RED_B; }
  readouts.push(mkText(msg, col, 22, [x0, -1.8, 0]));
  readouts.push(mkText('red segment = b·cos γ (shadow of b on a)', RED_B, 18, [x0, -2.5, 0]));
}

makeDraggable(dotA, scene, { constrainX: [-6.5, 0.5], constrainY: [-1.7, 2.4], onDrag: update });
makeDraggable(dotB, scene, { constrainX: [-4, 0.5], constrainY: [baseY, baseY], onDrag: update });

update();

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addButton({ label: 'Snap to right angle', onClick: () => {
  const A = dotA.getCenter();
  const h = Math.max(0.8, Math.hypot(A[0]-C[0], A[1]-C[1]));
  dotA.moveTo([C[0], Math.min(baseY + h, 2.4), 0]);
  update();
}});
controls.addButton({ label: 'Acute example', onClick: () => { dotA.moveTo([-3.2, 1.0, 0]); update(); } });
controls.addButton({ label: 'Obtuse example', onClick: () => { dotA.moveTo([-6.3, 0.5, 0]); update(); } });

await scene.wait(999999);"}

